    >
      {% content_for 'blocks' %}

      {%- if shop.password_message != blank -%}
        <div class="password-content">
          {{ shop.password_message }}
        </div>
      {%- endif -%}
    </div>
  </div>
</div>

{% stylesheet %}
  .section-password {
    flex-grow: 1;
    display: flex;
  }

  .password-content {
    text-align: center;
  }
{% endstylesheet %}

{% schema %}
